// === Tab: Vert ===
class Vert {
	constructor(x, y, v, c) {
		this.x = x;
		this.y = y;
		this.v = v;
		this.c = c;
		this.a = 0; // random(-0.025, 0.025); // random(TWO_PI);
		this.da = random(-0.1, 0.1)
	}

	draw(showArea = false) {
		push();
		translate(this.x, this.y)
		rotate(this.a)
		noStroke();
		strokeWeight(1);
		stroke(this.c)
		fill(this.c)
		beginShape();
    this.v.map((p) => vertex(p.x, p.y));
    endShape(CLOSE);
		if (showArea) {
			fill(0)
			textFont("Helvetica")
			textAlign(CENTER, CENTER);
			text("" + ~~this.getArea(), 0, 0)
		}
		pop();
	}

	getArea() {
		// https://www.geodose.com/2021/09/how-calculate-polygon-area-unordered-coordinates-points-python.html
		this.area = 0;
		let a1 = 0, a2 = 0;
		for (let i = 0; i < this.v.length; i++) {
			const p1 = this.v[i];
			const p2 = this.v[(i+1)%this.v.length];
			a1 += p1.x * p2.y;
			a2 += p1.y * p2.x;
		}
		this.area = abs(a1 - a2) / 2;
		return this.area;
	}
}

