	["#f43530", "#46454b", "#00aabb", "#e0e5da"],
	["#f77e5e", "#303030", "#3dbd5d", "#f4f4f4"],
	["#db2f27", "#e6c700", "#007500", "#008cbc"],
]).map((p) => p.map((e) => e + "FF"));

let palette;
let objs = [];

function setup() {
  createCanvas(S = max(windowWidth, windowHeight), S);
	palette = random(palettes);
	// palette.splice(0, 2);

	/*
  objs.push(createObj(S/4, S/4, S/4, 3));
  objs.push(createObj(S*3/4, S/4, S/4, 4));
  objs.push(createObj(S/4, S*3/4, S/4, 5));
  objs.push(createObj(S*3/4, S*3/4, S/4, 6));
	*/
	objs.push(createObj(S/2, S/2, S/2, ~~random(3, 8)));

  stroke(255);
  strokeWeight(2);
	strokeJoin(ROUND);
	strokeCap(SQUARE);
  noFill();
}

function draw() {
  background(32);
  for (let o of objs) {
		o.draw();
  }
	// noLoop() removed for animation
}

function mousePressed() {
  if (mouseButton === LEFT) {
    subdivideObj(objs);
    draw();
  }
}

function subdivideObj(objs) {
  // extract random vertex
  const idx = objs.length - ~~sqrt(random(pow(objs.length, 2))) - 1; // ~~random(objs.length);
  const [obj] = objs.splice(idx, 1);

	let x = obj.x;
	let y = obj.y;

	// interpolate 1/3 to another point
	if (false) {
		const p = random(obj.v);
		x = lerp(x, p.x, 1/3);
		y = lerp(y, p.y, 1/3);
	}

  // create and push new objects
  for (let i = 0; i < obj.v.length; i++) {
    const newVert = [];
		var p1 = obj.v[i];
		var p2 = obj.v[(i + 1) % obj.v.length];
		const cx = (3*x + p1.x + p2.x) / 3;
		const cy = (3*y + p1.y + p2.y) / 3;

		const dx = x - cx;
		const dy = y - cy;
		newVert.push({x: dx, y: dy});
    newVert.push({x: p1.x + dx, y: p1.y + dy});
    newVert.push({x: p2.x + dx, y: p2.y + dy});
    // newVert.push(p2);
		// newVert.map((p) => {p.x-=cx; p.y-=cy});
    objs.push(new Vert(cx, cy, newVert, (i === 0) ? obj.c : random(palette)));
  }
	// console.log(objs)
}

function createObj(cx, cy, r, n = 4) {
  const obj = [];
  for (let i = 0; i < n; i++) {
    const a = (i * TWO_PI) / n;
    var x = cos(a) * r;
    var y = sin(a) * r;
    obj.push({ x, y });
  }
  return new Vert(cx, cy, obj, random(palette));
}
